import { ApiError } from "./errors";
import type {
  ActionDecisionResponse,
  AgentApi,
  ChatResponse,
  ExecutionStatus,
  FileContent,
  FileList,
  LogEntry,
  LogsPage,
  PendingAction,
  PreviewInfo,
  Project,
  ProjectCreated,
  ProjectState,
  RunStatus,
  Task,
} from "./types";

/**
 * In-browser fake backend. It follows the same contract as the real API
 * (docs/api-contracts.md, docs/sprint3-contracts.md) and mirrors the Sprint 3 flow: one
 * `write_file` task per generated file, each logged as `write_file <path>`. Nothing here runs a
 * command or calls a model.
 *
 * "run <command>" asks for approval like a non-allowlisted command would. As in Sprint 3,
 * approving it still fails: `run_command` is closed this sprint.
 */
type SiteType = "blog" | "portfolio" | "landing";

const DEFAULT_TITLES: Record<SiteType, string> = {
  blog: "My Blog",
  portfolio: "My Portfolio",
  landing: "My Product",
};

const EXTRA_PAGES: Record<SiteType, { file: string; title: string }[]> = {
  blog: [{ file: "about.html", title: "About" }],
  portfolio: [{ file: "projects.html", title: "Projects" }],
  landing: [],
};

const APPROVAL_TTL_MS = 15 * 60 * 1000;

/** Same rules as backend/agent/planner.py: site type from keywords, title from "called X". */
export function classify(request: string): { siteType: SiteType; title: string } {
  const text = request.toLowerCase();
  const siteType: SiteType =
    text.includes("portfolio") || text.includes("resume") || /\bcv\b/.test(text)
      ? "portfolio"
      : text.includes("blog")
        ? "blog"
        : "landing";
  const named = /\b(?:called|named|titled|for)\s+(.+)$/i.exec(request);
  const title = (named?.[1] ?? "")
    .replace(/[\x00-\x1f\x7f"<>&]/g, " ")
    .replace(/\s+/g, " ")
    .replace(/^[ .!?']+|[ .!?']+$/g, "")
    .slice(0, 60)
    .trim();
  return { siteType, title: title || DEFAULT_TITLES[siteType] };
}

/** The generated site: relative path → text, like Rana's generator returns. */
export function fakeSite(siteType: SiteType, title: string): Record<string, string> {
  const pages = [{ file: "index.html", title: "Home" }, ...EXTRA_PAGES[siteType]];
  const nav = pages.map((p) => `<a href="${p.file}">${p.title}</a>`).join(" ");
  const files: Record<string, string> = {
    "style.css":
      "body{font-family:system-ui,sans-serif;margin:0;color:#1c2330}" +
      "header{background:#3b5bdb;color:#fff;padding:1rem}header a{color:#fff;margin-right:1rem}" +
      "main{max-width:48rem;margin:auto;padding:1rem}\n",
  };
  for (const page of pages) {
    files[page.file] =
      `<!doctype html>\n<html lang="en"><head><meta charset="utf-8">` +
      `<meta name="viewport" content="width=device-width, initial-scale=1">` +
      `<title>${page.title} · ${title}</title><link rel="stylesheet" href="style.css"></head>` +
      `<body><header><h1>${title}</h1><nav>${nav}</nav></header>` +
      `<main><h2>${page.title}</h2><p>A ${siteType} site generated by the mock API.</p></main>` +
      `</body></html>\n`;
  }
  return files;
}

/** Step prompts in the same format as backend/agent/orchestrator.py. */
export function fakePlan(request: string): string[] {
  const { siteType, title } = classify(request);
  const paths = Object.keys(fakeSite(siteType, title)).sort((a, b) =>
    a === "index.html" ? -1 : b === "index.html" ? 1 : a.localeCompare(b),
  );
  return paths.map((path) => `Write ${path} (${siteType} site "${title}")`);
}

interface MockExecution extends LogEntry {
  project_id: number;
}

export class MockAgentApi implements AgentApi {
  readonly mode = "mock" as const;
  private projects: Project[] = [];
  private tasks: Task[] = [];
  private executions: MockExecution[] = [];
  private files = new Map<number, Map<string, string>>();
  private nextProjectId = 1;
  private nextSessionId = 1;
  private nextTaskId = 1;
  private nextExecutionId = 1;

  constructor(private readonly latencyMs = 400) {}

  async health() {
    await this.delay();
    return { status: "ok" };
  }

  async createProject(name: string): Promise<ProjectCreated> {
    await this.delay();
    const trimmed = name.trim();
    if (!trimmed) throw validation("body.name", "String should have at least 1 character");
    const project: Project = {
      id: this.nextProjectId++,
      name: trimmed,
      created_at: new Date().toISOString(),
    };
    this.projects.push(project);
    this.files.set(project.id, new Map());
    return { ...project, session_id: this.nextSessionId++ };
  }

  async listProjects() {
    await this.delay();
    return this.projects.map((p) => ({ ...p }));
  }

  async sendChat(projectId: number, message: string): Promise<ChatResponse> {
    await this.delay();
    this.requireProject(projectId);
    if (!message.trim()) throw validation("body.message", "String should have at least 1 character");
    if (this.pending(projectId)) {
      throw new ApiError(409, {
        code: "pending_action_exists",
        message: "A command is waiting for approval.",
        project_id: projectId,
      });
    }

    const command = /^run\s+(.+)$/i.exec(message.trim())?.[1];
    if (command) {
      const task = this.addTask(projectId, `Run ${command}`, "waiting_for_approval");
      this.log(projectId, task.id, command, "pending_approval", {
        reason: "This command is not on the allowlist.",
      });
    } else {
      const { siteType, title } = classify(message);
      const site = fakeSite(siteType, title);
      const workspace = this.files.get(projectId)!;
      for (const step of fakePlan(message)) {
        const path = /^Write (\S+) /.exec(step)![1];
        const task = this.addTask(projectId, step, "succeeded");
        workspace.set(path, site[path]);
        this.log(projectId, task.id, `write_file ${path}`, "succeeded", {
          stdout: `wrote ${path} (${byteLength(site[path])} bytes)`,
          reason: `generated ${path} for a ${siteType} site`,
        });
      }
    }
    const state = this.state(projectId);
    return { ...state, message: describe(state) };
  }

  async getTasks(projectId: number) {
    await this.delay();
    this.requireProject(projectId);
    return this.state(projectId);
  }

  approveAction(actionId: number, commandHash: string) {
    return this.decide(actionId, true, commandHash);
  }

  rejectAction(actionId: number, commandHash: string) {
    return this.decide(actionId, false, commandHash);
  }

  async getLogs(projectId: number, afterId = 0, limit = 100): Promise<LogsPage> {
    await this.delay();
    this.requireProject(projectId);
    const entries = this.executions
      .filter((e) => e.project_id === projectId && e.id > afterId)
      .slice(0, limit)
      .map(({ project_id: _, ...entry }) => entry);
    return {
      project_id: projectId,
      entries,
      next_after_id: entries.length ? entries[entries.length - 1].id : afterId,
    };
  }

  async listFiles(projectId: number): Promise<FileList> {
    await this.delay();
    this.requireProject(projectId);
    const files = [...this.files.get(projectId)!.entries()]
      .map(([path, content]) => ({ path, size: byteLength(content) }))
      .sort((a, b) => a.path.localeCompare(b.path));
    return { project_id: projectId, files, truncated: false };
  }

  async getFileContent(projectId: number, path: string): Promise<FileContent> {
    await this.delay();
    this.requireProject(projectId);
    const content = this.files.get(projectId)!.get(path);
    if (content === undefined) {
      throw new ApiError(404, {
        code: "file_not_found",
        message: "No such file in the project.",
        project_id: projectId,
      });
    }
    return { project_id: projectId, path, size: byteLength(content), content };
  }

  async getPreview(projectId: number): Promise<PreviewInfo> {
    await this.delay();
    this.requireProject(projectId);
    const workspace = this.files.get(projectId)!;
    const index = workspace.get("index.html");
    if (index === undefined) return { project_id: projectId, status: "unavailable", url: null };
    // No server to serve the files from, so inline the stylesheet into a data: URL.
    const html = index.replace(
      '<link rel="stylesheet" href="style.css">',
      `<style>${workspace.get("style.css") ?? ""}</style>`,
    );
    return {
      project_id: projectId,
      status: "static",
      url: `data:text/html;charset=utf-8,${encodeURIComponent(html)}`,
    };
  }

  private async decide(
    actionId: number,
    approve: boolean,
    commandHash: string,
  ): Promise<ActionDecisionResponse> {
    await this.delay();
    const execution = this.executions.find((e) => e.id === actionId);
    if (!execution) {
      throw new ApiError(404, { code: "action_not_found", message: "No such action." });
    }
    const projectId = execution.project_id;
    const decision = approve ? "approved" : "rejected";
    if (execution.status !== "pending_approval") {
      const repeated = approve ? execution.status !== "rejected" : execution.status === "rejected";
      if (!repeated) {
        throw new ApiError(409, {
          code: "action_already_decided",
          message: `This request was already decided (${execution.status}).`,
          project_id: projectId,
        });
      }
      const state = this.state(projectId);
      const message = `This request was already ${decision}. ${describe(state)}`;
      return { ...state, action_id: actionId, decision, message };
    }
    if (commandHash !== fakeHash(projectId, execution.command)) {
      throw new ApiError(409, {
        code: "approval_mismatch",
        message: "The pending command changed since you reviewed it.",
        project_id: projectId,
      });
    }

    const task = this.tasks.find((t) => t.id === execution.task_id)!;
    if (approve) {
      execution.status = "failed";
      execution.stderr = "run_command is closed this sprint: no shell command was executed.";
      task.status = "failed";
    } else {
      execution.status = "rejected";
      task.status = "cancelled";
    }
    const state = this.state(projectId);
    return { ...state, action_id: actionId, decision, message: describe(state) };
  }

  private addTask(projectId: number, prompt: string, status: Task["status"]): Task {
    const task: Task = { id: this.nextTaskId++, project_id: projectId, type: "step", status, prompt };
    this.tasks.push(task);
    return task;
  }

  private log(
    projectId: number,
    taskId: number,
    command: string,
    status: ExecutionStatus,
    extra: Partial<LogEntry> = {},
  ) {
    this.executions.push({
      id: this.nextExecutionId++,
      project_id: projectId,
      task_id: taskId,
      command,
      status,
      stdout: "",
      stderr: "",
      output_truncated: false,
      retry_count: 0,
      duration_ms: status === "pending_approval" ? 0 : 3,
      reason: null,
      created_at: new Date().toISOString(),
      ...extra,
    });
  }

  private pending(projectId: number): PendingAction | null {
    const e = this.executions.find((x) => x.project_id === projectId && x.status === "pending_approval");
    if (!e) return null;
    return {
      id: e.id,
      task_id: e.task_id,
      command: e.command,
      command_hash: fakeHash(projectId, e.command),
      reason: e.reason,
      created_at: e.created_at,
      expires_at: new Date(Date.parse(e.created_at) + APPROVAL_TTL_MS).toISOString(),
    };
  }

  /** Same rules as compute_status in backend/api/services/tasks.py. */
  private state(projectId: number): ProjectState {
    const tasks = this.tasks.filter((t) => t.project_id === projectId).map((t) => ({ ...t }));
    const pending_action = this.pending(projectId);
    const last = tasks[tasks.length - 1];
    let status: RunStatus;
    if (pending_action) status = "waiting_for_approval";
    else if (!last) status = "idle";
    else if (tasks.some((t) => t.status === "running" || t.status === "pending")) status = "running";
    else if (last.status === "succeeded") status = "completed";
    else if (last.status === "failed" || last.status === "skipped") status = "failed";
    else if (last.status === "cancelled") status = "cancelled";
    else status = "running";
    return { project_id: projectId, status, tasks, pending_action };
  }

  private requireProject(projectId: number) {
    if (!this.projects.some((p) => p.id === projectId)) {
      throw new ApiError(404, {
        code: "project_not_found",
        message: "Project not found.",
        project_id: projectId,
      });
    }
  }

  private delay() {
    return new Promise<void>((r) => setTimeout(r, this.latencyMs));
  }
}

/** Same sentences as describe() in backend/api/services/tasks.py. */
function describe(state: ProjectState): string {
  if (state.pending_action) return `I need your approval to run: ${state.pending_action.command}`;
  const count = (s: Task["status"]) => state.tasks.filter((t) => t.status === s).length;
  const done = count("succeeded");
  if (state.status === "completed") return `Finished ${done} task(s).`;
  if (state.status === "failed") {
    return `Stopped after a failure: ${done} task(s) done, ${count("skipped")} not run.`;
  }
  if (state.status === "cancelled") return `Cancelled: ${done} task(s) done before it stopped.`;
  return "Working on it.";
}

/** Stand-in for the API's sha256 command hash: 64 hex chars, stable per project + command. */
function fakeHash(projectId: number, command: string): string {
  let h = 2166136261;
  for (const ch of `${projectId}:${command}`) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
  return h.toString(16).padStart(8, "0").repeat(8);
}

function byteLength(text: string): number {
  return new TextEncoder().encode(text).length;
}

function validation(field: string, message: string) {
  return new ApiError(422, {
    code: "validation_error",
    message: "Request validation failed.",
    details: [{ field, message, type: "string_too_short" }],
  });
}
